import type { Diagram, DiagramEdge, DiagramNode } from './types';
import type { ExternalSpec } from './enumerate';
import { sameTopology } from './topology';
import { validate } from './validate';

/**
 * Enumerates every topologically distinct tree-level QED diagram for an
 * arbitrary set of external particles (n ≥ 3).
 *
 * Unrooted trivalent trees with labelled leaves are generated by inserting
 * one leaf at a time on every existing edge ((2n − 5)!! shapes). Each shape is
 * then given every assignment of internal lines (photon or fermion in either
 * direction) and kept if it satisfies the QED vertex rule. External legs get
 * the arrow their species requires. Geometry is not computed (all at 0,0).
 */
export function enumerateTrees(externals: ExternalSpec[]): Diagram[] {
  const n = externals.length;
  if (n < 3) return [];
  type E = [string, string];
  const leaf = (i: number) => externals[i].id;
  let shapes: { edges: E[]; v: number }[] = [{ edges: [[leaf(0), 'v0'], [leaf(1), 'v0'], [leaf(2), 'v0']], v: 1 }];
  for (let i = 3; i < n; i++) {
    const next: typeof shapes = [];
    for (const s of shapes) {
      s.edges.forEach(([a, b], k) => {
        const nv = `v${s.v}`;
        const edges = s.edges.filter((_, j) => j !== k);
        edges.push([a, nv], [nv, b], [leaf(i), nv]);
        next.push({ edges, v: s.v + 1 });
      });
    }
    shapes = next;
  }

  const specs = new Map(externals.map((e) => [e.id, e]));
  const result: Diagram[] = [];
  for (const s of shapes) {
    const nodes: DiagramNode[] = [
      ...externals.map((e) => ({ id: e.id, kind: e.kind, x: 0, y: 0, expect: e.species })),
      ...Array.from({ length: s.v }, (_, i) => ({ id: `v${i}`, kind: 'vertex' as const, x: 0, y: 0 })),
    ];
    const ext: DiagramEdge[] = [];
    const internal: E[] = [];
    for (const [a, b] of s.edges) {
      const spec = specs.get(a) ?? specs.get(b);
      if (!spec) {
        internal.push([a, b]);
        continue;
      }
      const v = spec.id === a ? b : a;
      const id = spec.id;
      if (spec.species === 'gamma') ext.push({ id, type: 'photon', from: id, to: v });
      else {
        const into = spec.kind === 'in' ? spec.species === 'e-' : spec.species === 'e+';
        ext.push(into ? { id, type: 'fermion', from: id, to: v } : { id, type: 'fermion', from: v, to: id });
      }
    }
    const combos = 3 ** internal.length;
    for (let c = 0; c < combos; c++) {
      let k = c;
      const edges = [...ext];
      internal.forEach(([a, b], i) => {
        const t = k % 3;
        k = Math.floor(k / 3);
        const id = `i${i}`;
        edges.push(t === 0 ? { id, type: 'photon', from: a, to: b } : t === 1 ? { id, type: 'fermion', from: a, to: b } : { id, type: 'fermion', from: b, to: a });
      });
      const d = { nodes, edges };
      if (validate(d).ok && !result.some((r) => sameTopology(r, d))) result.push(d);
    }
  }
  return result;
}
